// ---- design parameters (docs/DESIGN.md §4) ----
constexpr uint32_t RING_DIM   = 65536;   // 2^16 (the size the backend runs; 128-bit at this logQ)
constexpr uint32_t MULT_DEPTH = 11;      // naive 8 + FLEXIBLEAUTO pessimism + spare
constexpr uint32_t SCALE_BITS = 45;
constexpr uint32_t FIRST_BITS = 60;
constexpr uint32_t SLOTS      = RING_DIM / 2;  // 32768 records per slot-batch

inline CCParams<CryptoContextCKKSRNS> designParams() {
    CCParams<CryptoContextCKKSRNS> p;
    p.SetRingDim(RING_DIM);
    p.SetMultiplicativeDepth(MULT_DEPTH);
    p.SetScalingModSize(SCALE_BITS);
    p.SetFirstModSize(FIRST_BITS);
    p.SetScalingTechnique(FLEXIBLEAUTO);
    p.SetSecurityLevel(HEStd_128_classic);
    p.SetBatchSize(SLOTS);
    return p;
}

// True when the first argument is --help or -h. Each stage then prints its
// usage and exits before touching any file.
inline bool helpRequested(int argc, char** argv) {
    if (argc < 2) return false;
    const std::string a = argv[1];
    return a == "--help" || a == "-h";
}

inline bool fileExists(const std::string& path) {
    struct stat st{};
    return stat(path.c_str(), &st) == 0;
}

inline size_t fileSize(const std::string& path) {
    struct stat st{};
    if (stat(path.c_str(), &st) != 0) return 0;
    return static_cast<size_t>(st.st_size);
}

struct Model {
    int F = 0, H = 0, deg = 0;
    std::vector<std::vector<double>> W1;      // F x H
    std::vector<double> b1, W2;               // H
    double b2 = 0;
    std::vector<double> domLo, domHi;         // H
    std::vector<std::vector<double>> cheb;    // H x (deg+1)
};

inline Model loadModel(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("Cannot open " + path);
    Model m;
    in >> m.F >> m.H >> m.deg;
    m.W1.assign(m.F, std::vector<double>(m.H));
    for (auto& row : m.W1) for (auto& v : row) in >> v;
    m.b1.resize(m.H);  for (auto& v : m.b1) in >> v;
    m.W2.resize(m.H);  for (auto& v : m.W2) in >> v;
    in >> m.b2;
    m.domLo.resize(m.H); m.domHi.resize(m.H);
    m.cheb.assign(m.H, std::vector<double>(m.deg + 1));
    for (int k = 0; k < m.H; ++k) {
        in >> m.domLo[k] >> m.domHi[k];
        for (auto& c : m.cheb[k]) in >> c;
    }
    if (!in) throw std::runtime_error("Malformed model file: " + path);
    return m;
}

// CSV of standardized features: one record per line, F comma-separated values.
inline std::vector<std::vector<double>> loadCsv(const std::string& path, size_t maxRows) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("Cannot open " + path);
    std::vector<std::vector<double>> rows;
    std::string line;
    while (rows.size() < maxRows && std::getline(in, line)) {
        if (line.empty()) continue;
        std::vector<double> r;
        std::stringstream ss(line);
        std::string cell;
        while (std::getline(ss, cell, ',')) r.push_back(std::stod(cell));
        rows.push_back(std::move(r));
    }
    return rows;
}

template <typename T>
inline void mustDeserialize(T& obj, const std::string& path) {
    if (!Serial::DeserializeFromFile(path, obj, SerType::BINARY))
        throw std::runtime_error("Cannot deserialize " + path);
}

template <typename T>
inline void mustSerialize(const T& obj, const std::string& path) {
    if (!Serial::SerializeToFile(path, obj, SerType::BINARY))
        throw std::runtime_error("Cannot serialize " + path);
}
